/** Structured page content generated by scripts/content/import-content.mjs. */

export type Inline =
  | { text: string; href?: string; strong?: boolean; type?: undefined }
  /** Placeholder for the support email address (configured, see config/business.ts). */
  | { type: 'support-email'; text: string };

export type Block =
  | { type: 'p'; content: Inline[] }
  | { type: 'h3'; text: string }
  | { type: 'ul' | 'ol'; items: Inline[][] }
  | { type: 'dl'; items: { term: string; details: Inline[] }[] }
  | { type: 'table'; head: string[]; rows: Inline[][][] };

export interface ContentSection {
  id: string | null;
  title: string | null;
  blocks: Block[];
}

export interface ContentPage {
  slug: string;
  eyebrow: string | null;
  title: string;
  updated: { iso: string; label: string } | null;
  intro: Inline[][];
  summary: { title: string; items: { title: string; text: Inline[] }[]; note: Inline[] | null } | null;
  sections: ContentSection[];
  /** Long documents get a table of contents. */
  toc: boolean;
}

export interface FaqEntry {
  question: string;
  answer: string;
}

export interface CreditEntry {
  subject: string;
  author: string | null;
  authorUrl: string | null;
  sourceUrl: string | null;
}
